// Good example: parallel data fetching
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 1000 },
      notifications: [{ id: 1, message: 'Notification 1' }],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>
      <div>
        <h3>Analytics</h3>
        <p>Views: {analytics?.views}</p>
        <pre>{JSON.stringify(analytics, null, 2)}</pre>
      </div>
      <div>
        <h3>Notifications</h3>
        <p>Notifications: {Array.isArray(notifications) ? notifications.length : 0}</p>
        <ul>
          {Array.isArray(notifications) &&
            notifications.map((notification: any, index: number) => (
              <li key={notification.id ?? index}>
                {notification.message ?? notification.title ?? JSON.stringify(notification)}
              </li>
            ))}
        </ul>
        <pre>{JSON.stringify(notifications, null, 2)}</pre>
      </div>
      <div>
        <h3>Settings</h3>
        <p>Theme: {settings?.theme}</p>
        <pre>{JSON.stringify(settings, null, 2)}</pre>
      </div>
    </div>
  )
}

